'use strict';

// MODULES //

var isInt64 = require( '@stdlib/assert-is-int64' );
var toWords = require( '@stdlib/number-int64-base-to-words' ).assign;
var Int64 = require( '@stdlib/number-int64-ctor' );
var format = require( '@stdlib/string-format' );


// MAIN //

/**
* Returns an array of iterated values.
*
* @private
* @param {Object} it - iterator
* @returns {(Array|TypeError)} array or an error
*/
function fromIterator( it ) {
	var words;
	var out;
	var v;
	var u;

	// Workspace for storing high and low words:
	words = [ 0, 0 ];

	out = [];
	while ( true ) {
		v = it.next();
		if ( v.done ) {
			break;
		}
		u = v.value;
		if ( !isInt64( u ) ) {
			try {
				u = new Int64( u );
			} catch ( err ) { // eslint-disable-line no-unused-vars
				return new TypeError( format( 'invalid argument. An iterator must return either a 64-bit signed integer or a value which can be converted to a 64-bit signed integer. Value: `%s`.', u ) );
			}
		}
		toWords( u, words, 1, 0 );
		out.push( words[ 0 ], words[ 1 ] );
	}
	return out;
}


// EXPORTS //

module.exports = fromIterator;
